# ---------------------------------------------------------------------------
# helpers -- a tiny DER reader so the fingerprint is checked against an
# independent oracle rather than against the module's own encoder.
# ---------------------------------------------------------------------------


def _der_read_tlv(blob: bytes, offset: int) -> tuple[int, bytes, int]:
    """Read one ASN.1 TLV, returning ``(tag, value, next_offset)``."""
    tag = blob[offset]
    length = blob[offset + 1]
    cursor = offset + 2
    if length & 0x80:
        count = length & 0x7F
        length = int.from_bytes(blob[cursor:cursor + count], "big")
        cursor += count
    return tag, blob[cursor:cursor + length], cursor + length


def _der_children(blob: bytes) -> list[tuple[int, bytes]]:
    """Split a DER blob into its top-level ``(tag, value)`` children."""
    out: list[tuple[int, bytes]] = []
    cursor = 0
    while cursor < len(blob):
        tag, value, cursor = _der_read_tlv(blob, cursor)
        out.append((tag, value))
    return out


def _subject_public_key_info(cert_der: bytes) -> bytes:
    """Return the DER ``SubjectPublicKeyInfo`` out of a DER certificate."""
    _, certificate_body, _ = _der_read_tlv(cert_der, 0)
    tbs = _der_children(certificate_body)[0][1]
    fields = _der_children(tbs)
    # version [0], serial, signature, issuer, validity, subject, SubjectPublicKeyInfo
    spki = fields[6]
    assert spki[0] == 0x30, "expected a SubjectPublicKeyInfo SEQUENCE"
    return spki[1]


def _spki_fingerprint(cert_path: Path) -> str:
    """SHA-256 of the certificate's DER SubjectPublicKeyInfo (the standard pin)."""
    cert_der = ssl.PEM_cert_to_DER_cert(cert_path.read_text(encoding="utf-8"))
    return hashlib.sha256(_subject_public_key_info(cert_der)).hexdigest()


def _der_common_name(cert_path: Path) -> str:
    """Read the subject CN out of the DER certificate (an independent oracle)."""
    cert_der = ssl.PEM_cert_to_DER_cert(cert_path.read_text(encoding="utf-8"))
    _, certificate_body, _ = _der_read_tlv(cert_der, 0)
    tbs = _der_children(certificate_body)[0][1]
    fields = _der_children(tbs)
    # version [0], serial, signature, issuer, validity, subject, SubjectPublicKeyInfo
    rdn = _der_children(fields[5][1])[0][1]        # the subject's first RDN
    attribute = _der_children(rdn)[0][1]           # its first AttributeTypeValue
    return _der_children(attribute)[1][1].decode("utf-8")


def _verified_client_context(cert_path: Path) -> ssl.SSLContext:
    """A client context that verifies chain *and* hostname against our own CA."""
    context = ssl.create_default_context(cafile=str(cert_path))
    context.check_hostname = True
    context.verify_mode = ssl.CERT_REQUIRED
    return context


def _get(context: ssl.SSLContext, url: str) -> tuple[int, bytes]:
    with urllib.request.urlopen(url, context=context, timeout=15) as response:
        return response.status, response.read()


# ---------------------------------------------------------------------------
# Windows ACL oracles -- deliberately built from the Win32 API rather than from
# anything the module under test exposes, so they are independent evidence.
# ---------------------------------------------------------------------------


def _current_user_sid() -> str:
    """The current user's SID, from an oracle that is not the module under test."""
    system_root = os.environ.get("SystemRoot", r"C:\Windows")
    whoami = Path(system_root) / "System32" / "whoami.exe"
    completed = subprocess.run(
        [str(whoami), "/user", "/fo", "csv", "/nh"],
        capture_output=True,
        encoding="mbcs",
        errors="replace",
        check=True,
        timeout=60,
    )
    return next(csv.reader(io.StringIO(completed.stdout)))[1]


def _dacl_facts(key_path: Path) -> tuple[bool, list[str]]:
    """Read a file's DACL back as ``(protected from inheritance, granted SIDs)``."""
    import ctypes

    advapi32 = ctypes.windll.advapi32
    kernel32 = ctypes.windll.kernel32
    flags = 0x00000004 | 0x80000000  # DACL_SECURITY_INFORMATION | PROTECTED_DACL_SECURITY_INFORMATION

    advapi32.GetFileSecurityW.argtypes = [
        ctypes.c_wchar_p, ctypes.c_ulong, ctypes.c_void_p, ctypes.c_ulong,
        ctypes.POINTER(ctypes.c_ulong),
    ]
    advapi32.GetFileSecurityW.restype = ctypes.c_int
    advapi32.GetSecurityDescriptorControl.argtypes = [
        ctypes.c_void_p, ctypes.POINTER(ctypes.c_ushort), ctypes.POINTER(ctypes.c_ulong),
    ]
    advapi32.GetSecurityDescriptorControl.restype = ctypes.c_int
    advapi32.GetSecurityDescriptorDacl.argtypes = [
        ctypes.c_void_p, ctypes.POINTER(ctypes.c_int),
        ctypes.POINTER(ctypes.c_void_p), ctypes.POINTER(ctypes.c_int),
    ]
    advapi32.GetSecurityDescriptorDacl.restype = ctypes.c_int
    advapi32.GetAclInformation.argtypes = [ctypes.c_void_p, ctypes.c_void_p, ctypes.c_ulong, ctypes.c_ulong]
    advapi32.GetAclInformation.restype = ctypes.c_int
    advapi32.GetAce.argtypes = [ctypes.c_void_p, ctypes.c_ulong, ctypes.POINTER(ctypes.c_void_p)]
    advapi32.GetAce.restype = ctypes.c_int
    advapi32.ConvertSidToStringSidW.argtypes = [ctypes.c_void_p, ctypes.POINTER(ctypes.c_void_p)]
    advapi32.ConvertSidToStringSidW.restype = ctypes.c_int

    needed = ctypes.c_ulong(0)
    advapi32.GetFileSecurityW(str(key_path), flags, None, 0, ctypes.byref(needed))
    assert needed.value, "the key file's security descriptor could not be sized"
    descriptor = ctypes.create_string_buffer(needed.value)
    assert advapi32.GetFileSecurityW(
        str(key_path), flags, descriptor, needed.value, ctypes.byref(needed)
    )

    control = ctypes.c_ushort()
    revision = ctypes.c_ulong()
    assert advapi32.GetSecurityDescriptorControl(descriptor, ctypes.byref(control), ctypes.byref(revision))
    protected = bool(control.value & 0x1000)  # SE_DACL_PROTECTED

    present = ctypes.c_int()
    defaulted = ctypes.c_int()
    dacl = ctypes.c_void_p()
    assert advapi32.GetSecurityDescriptorDacl(
        descriptor, ctypes.byref(present), ctypes.byref(dacl), ctypes.byref(defaulted)
    )
    if not present.value or not dacl.value:
        return protected, []

    counts = (ctypes.c_ulong * 3)()  # ACL_SIZE_INFORMATION: AceCount first
    assert advapi32.GetAclInformation(dacl, ctypes.byref(counts), ctypes.sizeof(counts), 2)
    sids: list[str] = []
    for index in range(counts[0]):
        ace = ctypes.c_void_p()
        assert advapi32.GetAce(dacl, index, ctypes.byref(ace))
        # ACCESS_ALLOWED_ACE is ACE_HEADER (4 bytes) + ACCESS_MASK (4) + SidStart,
        # so the SID the ACE applies to sits eight bytes into the ACE.
        sid = ctypes.cast(ctypes.c_void_p(ace.value + 8), ctypes.c_void_p)
        text = ctypes.c_void_p()
        assert advapi32.ConvertSidToStringSidW(sid, ctypes.byref(text))
        try:
            sids.append(ctypes.wstring_at(text.value))
        finally:
            kernel32.LocalFree(text)
    return protected, sids


