@pytest.fixture(scope="module")
def cert_dir(tmp_path_factory: pytest.TempPathFactory) -> Path:
    """One certificate for the whole module: key generation is the slow part."""
    directory = tmp_path_factory.mktemp("cert")
    generate_self_signed_certificate(directory)
    return directory


@pytest.fixture
def pkg_root(tmp_path: Path) -> Path:
    """A package directory with two packages, one plain file and one nested file."""
    root = tmp_path / "packages"
    root.mkdir()
    (root / "app.ipa").write_bytes(b"IPA-PAYLOAD-ONE")
    (root / "lib.dylib").write_bytes(b"DYLIB-PAYLOAD-TWO")
    (root / "notes.txt").write_text("not a package", encoding="utf-8")
    nested = root / "nested"
    nested.mkdir()
    (nested / "inner.ipa").write_bytes(b"NESTED-PAYLOAD")
    return root


@pytest.fixture
def server(pkg_root: Path, cert_dir: Path) -> PackageServer:
    """A running TLS package server bound to an ephemeral loopback port."""
    with PackageServer(root=pkg_root, cert_directory=cert_dir, port=0) as running:
        yield running


# ---------------------------------------------------------------------------
# 1. certificate generation
# ---------------------------------------------------------------------------


class TestCertificateGeneration:
    def test_writes_certificate_and_key_pem(self, cert_dir: Path) -> None:
        material = generate_self_signed_certificate(cert_dir)
        assert material.cert_path.is_file()
        assert material.key_path.is_file()
        certificate = material.cert_path.read_text(encoding="utf-8")
        assert certificate.startswith("-----BEGIN CERTIFICATE-----")
        # The key is written as a PEM too, but the *material* object never
        # carries it, so it cannot be echoed by an accident of repr().
        assert "PRIVATE KEY" not in repr(material)

    def test_fingerprint_is_the_sha256_of_the_der_spki(self, cert_dir: Path) -> None:
        material = generate_self_signed_certificate(cert_dir)
        expected = _spki_fingerprint(material.cert_path)
        assert material.fingerprint == expected
        assert len(material.fingerprint) == 64
        assert material.fingerprint == material.fingerprint.lower()

    def test_fingerprint_is_stable_for_the_same_directory(self, cert_dir: Path) -> None:
        first = generate_self_signed_certificate(cert_dir)
        second = generate_self_signed_certificate(cert_dir)
        assert first.fingerprint == second.fingerprint
        assert first.cert_path == second.cert_path

    def test_fresh_key_per_directory(self, tmp_path: Path) -> None:
        one = generate_self_signed_certificate(tmp_path / "one")
        two = generate_self_signed_certificate(tmp_path / "two")
        assert one.fingerprint != two.fingerprint

    def test_san_covers_the_guest_gateway_and_loopback(self, cert_dir: Path) -> None:
        # The names are read back out of the certificate, not echoed from the
        # request, so this also proves the SAN really made it onto the wire.
        material = generate_self_signed_certificate(cert_dir)
        assert DEFAULT_GUEST_GATEWAY in material.san_ips
        assert "localhost" in material.san_hosts
        assert DEFAULT_LOOPBACK_HOST in material.san_hosts

    def test_a_new_name_renews_the_certificate(self, tmp_path: Path) -> None:
        # Reuse must not hand back a material describing a certificate that
        # does not carry the name the caller just asked for.
        first = generate_self_signed_certificate(tmp_path, san_hosts=("localhost",))
        second = generate_self_signed_certificate(tmp_path, san_hosts=("localhost", "extra.example"))
        assert second.fingerprint != first.fingerprint
        assert "extra.example" in second.san_hosts

    def test_key_file_is_not_world_readable(self, cert_dir: Path) -> None:
        material = generate_self_signed_certificate(cert_dir)
        mode = material.key_path.stat().st_mode & 0o777
        # Windows ignores POSIX bits, so only assert where they are honoured.
        if Path("/proc/self").exists():  # pragma: no cover - Windows host
            assert mode == 0o600

    def test_invalid_san_is_a_config_error(self, tmp_path: Path) -> None:
        with pytest.raises(UniPadError) as excinfo:
            generate_self_signed_certificate(tmp_path, san_hosts=("bad host!",))
        assert excinfo.value.code == ErrorCode.CONFIG_INVALID

    def test_unwritable_directory_reports_no_key_material(self, tmp_path: Path) -> None:
        blocker = tmp_path / "blocker"
        blocker.write_bytes(b"not a directory")
        with pytest.raises(UniPadError) as excinfo:
            generate_self_signed_certificate(blocker / "nested")
        rendered = json.dumps(excinfo.value.to_dict(), ensure_ascii=False)
        assert "BEGIN" not in rendered
        assert "PRIVATE KEY" not in rendered


# ---------------------------------------------------------------------------
# 2. the package server over a real TLS connection
# ---------------------------------------------------------------------------


class TestPackageServerTls:
    def test_index_json_lists_packages_with_sha256(self, server: PackageServer, pkg_root: Path) -> None:
        context = _verified_client_context(server.cert_path)
        status, body = _get(context, f"{server.url}{INDEX_PATH}")
        assert status == 200
        payload = json.loads(body)

        names = [entry["name"] for entry in payload["packages"]]
        assert names == sorted(names)                       # stable ordering
        # Every regular file directly in the root is indexed; the policy is
        # "one directory", not "one file extension".
        assert names == ["app.ipa", "lib.dylib", "notes.txt"]
        for entry in payload["packages"]:
            digest = hashlib.sha256((pkg_root / entry["name"]).read_bytes()).hexdigest()
            assert entry["sha256"] == digest
            assert entry["size"] == (pkg_root / entry["name"]).stat().st_size

    def test_nested_package_is_reachable(self, server: PackageServer, pkg_root: Path) -> None:
        context = _verified_client_context(server.cert_path)
        status, body = _get(context, f"{server.url}/packages/nested/inner.ipa")
        assert status == 200
        assert body == (pkg_root / "nested" / "inner.ipa").read_bytes()

    def test_index_is_byte_stable_across_calls(self, server: PackageServer) -> None:
        context = _verified_client_context(server.cert_path)
        _, first = _get(context, f"{server.url}{INDEX_PATH}")
        _, second = _get(context, f"{server.url}{INDEX_PATH}")
        assert first == second

    def test_package_bytes_are_served_over_verified_tls(self, server: PackageServer, pkg_root: Path) -> None:
        context = _verified_client_context(server.cert_path)
        status, body = _get(context, f"{server.url}/packages/app.ipa")
        assert status == 200
        assert body == (pkg_root / "app.ipa").read_bytes()

    def test_root_serves_the_index(self, server: PackageServer) -> None:
        context = _verified_client_context(server.cert_path)
        status, body = _get(context, server.url)
        assert status == 200
        assert json.loads(body)["packages"]

    def test_guest_url_points_at_the_qemu_gateway(self, server: PackageServer) -> None:
        assert server.guest_url == f"https://{DEFAULT_GUEST_GATEWAY}:{server.port}{INDEX_PATH}"

    def test_missing_package_is_404(self, server: PackageServer) -> None:
        context = _verified_client_context(server.cert_path)
        with pytest.raises(urllib.error.HTTPError) as excinfo:
            _get(context, f"{server.url}/packages/nope.ipa")
        assert excinfo.value.code == 404

    def test_plaintext_http_is_refused(self, server: PackageServer) -> None:
        # TLS is the only way in unless a caller explicitly opts out.
        with pytest.raises(Exception):
            urllib.request.urlopen(f"http://127.0.0.1:{server.port}{INDEX_PATH}", timeout=10)


# ---------------------------------------------------------------------------
# 3. path traversal
# ---------------------------------------------------------------------------


class TestPathTraversal:
    @pytest.mark.parametrize(
        "path",
        [
            "/packages/../../../etc/passwd",
            "/packages/..%2f..%2f..%2fetc%2fpasswd",
            "/packages/%2e%2e%2f%2e%2e%2fetc%2fpasswd",
            "/..%252f..%252fetc%252fpasswd",
            "/packages/....//....//etc/passwd",
            "/etc/passwd",
            "//etc/passwd",
            "/packages/..\\..\\etc\\passwd",
            "/packages/./../../etc/passwd",
        ],
    )
    def test_escape_attempts_are_rejected(self, server: PackageServer, path: str) -> None:
        context = _verified_client_context(server.cert_path)
        url = f"{server.url}{path}"
        with pytest.raises(urllib.error.HTTPError) as excinfo:
            _get(context, url)
        assert excinfo.value.code in (400, 404)

    def test_symlink_out_of_the_root_is_rejected(self, tmp_path: Path, cert_dir: Path) -> None:
        outside = tmp_path / "outside"
        outside.mkdir()
        secret = outside / "secret.txt"
        secret.write_text("TOP-SECRET", encoding="utf-8")

        root = tmp_path / "root"
        root.mkdir()
        (root / "app.ipa").write_bytes(b"payload")
        try:
            (root / "escape.txt").symlink_to(secret)
        except OSError:  # pragma: no cover - needs no privilege on Windows dev builds
            pytest.skip("symlink creation unavailable on this host")

        with PackageServer(root=root, cert_directory=cert_dir, port=0) as running:
            context = _verified_client_context(running.cert_path)
            with pytest.raises(urllib.error.HTTPError) as excinfo:
                _get(context, f"{running.url}/packages/escape.txt")
            assert excinfo.value.code in (400, 404)

    def test_no_directory_listing(self, server: PackageServer) -> None:
        context = _verified_client_context(server.cert_path)
        with pytest.raises(urllib.error.HTTPError) as excinfo:
            _get(context, f"{server.url}/packages/")
        assert excinfo.value.code in (400, 404)

    def test_resolver_rule_without_needing_symlinks(self, pkg_root: Path) -> None:
        # The symlink case below needs a privilege Windows does not grant by
        # default, so the resolution *rule* is also asserted directly: only a
        # regular file inside the root ever resolves.
        handler = PackageRequestHandler.__new__(PackageRequestHandler)
        handler.server = SimpleNamespace(package_root=pkg_root)  # type: ignore[attr-defined]

        assert handler._resolve("nested/inner.ipa") is not None
        assert handler._resolve("") is None
        assert handler._resolve("/etc/passwd") is None
        assert handler._resolve("..\\..\\etc\\passwd") is None
        assert handler._resolve("missing.ipa") is None
        # The root itself is a directory, never a deliverable "file".
        assert handler._resolve("nested") is None


# ---------------------------------------------------------------------------
# 4. nothing sensitive is ever emitted
# ---------------------------------------------------------------------------


class TestNoSecretsInOutput:
    def test_package_contents_never_appear_in_the_log(
        self, server: PackageServer, pkg_root: Path, caplog: pytest.LogCaptureFixture
    ) -> None:
        context = _verified_client_context(server.cert_path)
        with caplog.at_level(logging.DEBUG, logger="unipad.host.httpsvc"):
            _get(context, f"{server.url}/packages/app.ipa")
            _get(context, f"{server.url}{INDEX_PATH}")
        for record in caplog.records:
            assert b"IPA-PAYLOAD-ONE" not in record.getMessage().encode()

    def test_private_key_never_appears_in_the_log(self, server: PackageServer, caplog: pytest.LogCaptureFixture) -> None:
        key_pem = server.key_path.read_text(encoding="utf-8")
        key_body = "".join(
            line for line in key_pem.splitlines() if "-----" not in line
        )
        context = _verified_client_context(server.cert_path)
        with caplog.at_level(logging.DEBUG, logger="unipad.host.httpsvc"):
            _get(context, f"{server.url}/packages/app.ipa")
        assert key_body not in caplog.text

    def test_request_handler_errors_do_not_leak_locals(
        self, server: PackageServer, caplog: pytest.LogCaptureFixture
    ) -> None:
        # A traceback can carry local variables; a private key must never be
        # reachable that way, so the server logs the exception type only.
        try:
            raise ValueError("boom carrying secret material")
        except ValueError:
            server.server.handle_error(None, ("127.0.0.1", 0))
        assert "boom carrying secret material" not in caplog.text
        assert "ValueError" in caplog.text
        assert "Traceback" not in caplog.text

    def test_index_digests_match_the_files_but_are_not_the_files(
        self, server: PackageServer, pkg_root: Path
    ) -> None:
        context = _verified_client_context(server.cert_path)
        _, body = _get(context, f"{server.url}{INDEX_PATH}")
        payload = json.loads(body)
        raw = (pkg_root / "app.ipa").read_bytes()
        assert raw not in body


# ---------------------------------------------------------------------------
# 5. security defaults
# ---------------------------------------------------------------------------


class TestSecurityDefaults:
    def test_bind_defaults_to_loopback_only(self, pkg_root: Path, cert_dir: Path) -> None:
        with PackageServer(root=pkg_root, cert_directory=cert_dir, port=0) as running:
            assert running.host == DEFAULT_LOOPBACK_HOST

    @pytest.mark.parametrize("host", ["0.0.0.0", "::", "192.168.1.10"])
    def test_non_loopback_bind_requires_an_explicit_opt_in(
        self, pkg_root: Path, cert_dir: Path, host: str
    ) -> None:
        with pytest.raises(UniPadError) as excinfo:
            PackageServer(root=pkg_root, cert_directory=cert_dir, host=host, port=0)
        assert excinfo.value.code == ErrorCode.CONFIG_INVALID

    def test_plaintext_requires_an_explicit_opt_in(self, pkg_root: Path, cert_dir: Path) -> None:
        with pytest.raises(UniPadError) as excinfo:
            PackageServer(root=pkg_root, cert_directory=cert_dir, port=0, tls=False)
        assert excinfo.value.code == ErrorCode.CONFIG_INVALID

    def test_plaintext_works_once_opted_in(self, pkg_root: Path) -> None:
        # The escape hatch exists for tests that only exercise routing.
        with PackageServer(
            root=pkg_root, port=0, tls=False, allow_plaintext=True
        ) as running:
            status, body = _get(
                ssl.create_default_context(), f"{running.url}{INDEX_PATH}"
            )
            assert status == 200
            assert json.loads(body)["packages"]

    def test_missing_root_is_a_config_error(self, tmp_path: Path, cert_dir: Path) -> None:
        with pytest.raises(UniPadError) as excinfo:
            PackageServer(root=tmp_path / "absent", cert_directory=cert_dir, port=0)
        assert excinfo.value.code == ErrorCode.CONFIG_INVALID

    def test_root_must_be_a_directory(self, tmp_path: Path, cert_dir: Path) -> None:
        plain = tmp_path / "plain.bin"
        plain.write_bytes(b"x")
        with pytest.raises(UniPadError) as excinfo:
            PackageServer(root=plain, cert_directory=cert_dir, port=0)
        assert excinfo.value.code == ErrorCode.CONFIG_INVALID

    def test_invalid_port_is_a_config_error(self, pkg_root: Path, cert_dir: Path) -> None:
        with pytest.raises(UniPadError) as excinfo:
            PackageServer(root=pkg_root, cert_directory=cert_dir, port=-1)
        assert excinfo.value.code == ErrorCode.CONFIG_INVALID

    def test_no_store_cache_header(self, server: PackageServer) -> None:
        context = _verified_client_context(server.cert_path)
        with urllib.request.urlopen(f"{server.url}{INDEX_PATH}", context=context, timeout=15) as response:
            assert response.headers["Cache-Control"] == "no-store"


# ---------------------------------------------------------------------------
# 6. lifecycle
# ---------------------------------------------------------------------------


class TestLifecycle:
    def test_port_zero_yields_a_real_port(self, server: PackageServer) -> None:
        assert server.port > 0
        assert f":{server.port}" in server.url

    def test_stop_releases_the_port(self, pkg_root: Path, cert_dir: Path) -> None:
        running = PackageServer(root=pkg_root, cert_directory=cert_dir, port=0)
        running.start()
        port = running.port
        running.stop()
        # Re-binding the same port must now succeed, proving the socket closed.
        import socket

        with socket.socket() as probe:
            probe.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            probe.bind((DEFAULT_LOOPBACK_HOST, port))

    def test_stop_is_idempotent(self, pkg_root: Path, cert_dir: Path) -> None:
        running = PackageServer(root=pkg_root, cert_directory=cert_dir, port=0)
        running.start()
        running.stop()
        running.stop()

    def test_context_manager_starts_and_stops(self, pkg_root: Path, cert_dir: Path) -> None:
        with PackageServer(root=pkg_root, cert_directory=cert_dir, port=0) as running:
            assert running.is_running
            context = _verified_client_context(running.cert_path)
            status, _ = _get(context, f"{running.url}{INDEX_PATH}")
            assert status == 200
        assert not running.is_running

    def test_context_manager_stops_on_error(self, pkg_root: Path, cert_dir: Path) -> None:
        with pytest.raises(RuntimeError):
            with PackageServer(root=pkg_root, cert_directory=cert_dir, port=0):
                raise RuntimeError("caller failure")
        # The port must be free again; otherwise the failure leaked a socket.
        import socket

        with socket.socket() as probe:
            probe.bind((DEFAULT_LOOPBACK_HOST, 0))

    def test_start_twice_is_rejected(self, pkg_root: Path, cert_dir: Path) -> None:
        running = PackageServer(root=pkg_root, cert_directory=cert_dir, port=0)
        running.start()
        try:
            with pytest.raises(UniPadError):
                running.start()
        finally:
            running.stop()

    def test_start_generates_a_certificate_when_none_is_given(self, pkg_root: Path, tmp_path: Path) -> None:
        # The caller-chosen directory is created on demand so the service is
        # usable without a separate provisioning step.
        with PackageServer(
            root=pkg_root, cert_directory=tmp_path / "fresh", port=0
        ) as running:
            assert running.cert_path.is_file()
            context = _verified_client_context(running.cert_path)
            status, _ = _get(context, f"{running.url}{INDEX_PATH}")
            assert status == 200

    def test_default_certificate_directory_is_private_per_instance(self, pkg_root: Path) -> None:
        # A predictable shared path would let another local user read the
        # private key or pre-seed a certificate of their own choosing.
        with PackageServer(root=pkg_root, port=0) as first:
            with PackageServer(root=pkg_root, port=0) as second:
                assert first.material.cert_directory != second.material.cert_directory
                assert first.material.cert_directory.name.startswith("unipad-httpsvc-")

    def test_port_in_use_is_a_transfer_error(self, pkg_root: Path, cert_dir: Path) -> None:
        import socket

        with socket.socket() as occupied:
            occupied.bind((DEFAULT_LOOPBACK_HOST, 0))
            occupied.listen(1)
            port = occupied.getsockname()[1]
            with pytest.raises(UniPadError) as excinfo:
                PackageServer(root=pkg_root, cert_directory=cert_dir, port=port).start()
        assert excinfo.value.code == ErrorCode.TRANSFER_FAILED


