class TestPrivateKeyAccessControl:
    """``os.chmod`` cannot restrict a file on Windows, so the DACL has to."""

    @pytest.mark.skipif(os.name != "nt", reason="the DACL path is Windows-only")
    def test_the_key_dacl_grants_only_the_current_user(self, tmp_path: Path) -> None:
        material = generate_self_signed_certificate(tmp_path)
        protected, sids = _dacl_facts(material.key_path)
        # Inheritance must be cut: a shared or repo-relative certificate
        # directory would otherwise widen the key to everyone who can read it.
        assert protected is True
        assert sids == [_current_user_sid()]
        # Restricting must not lock the service itself out of its own key.
        assert material.key_path.read_bytes().startswith(b"-----BEGIN EC PRIVATE KEY-----")

    @pytest.mark.skipif(os.name != "nt", reason="the DACL path is Windows-only")
    def test_the_restriction_is_repeatable(self, tmp_path: Path) -> None:
        # The owner keeps WRITE_DAC, so a second pass must still succeed rather
        # than silently leaving the first (possibly wider) DACL in place.
        material = generate_self_signed_certificate(tmp_path)
        httpsvc._restrict_key_permissions(material.key_path)
        assert _dacl_facts(material.key_path) == (True, [_current_user_sid()])

    @pytest.mark.skipif(os.name != "nt", reason="the DACL path is Windows-only")
    def test_a_renewal_can_still_rewrite_the_key(self, tmp_path: Path) -> None:
        # The restriction must not wedge the renewal path: a certificate that
        # is close to expiry is rewritten in place, so the ACE has to carry
        # write as well as read.
        first = generate_self_signed_certificate(tmp_path, validity_days=1)
        assert first.days_remaining <= 1
        second = generate_self_signed_certificate(tmp_path)
        assert second.fingerprint != first.fingerprint

    @pytest.mark.skipif(os.name != "nt", reason="the DACL path is Windows-only")
    def test_a_failed_restriction_is_announced_but_not_fatal(
        self, tmp_path: Path, monkeypatch: pytest.MonkeyPatch, caplog: pytest.LogCaptureFixture
    ) -> None:
        # A security control that fails silently is the defect being fixed, so
        # the failure has to be visible -- without carrying the path (PRD 9.2).
        material = generate_self_signed_certificate(tmp_path)

        def refuse(*args: object, **kwargs: object) -> None:
            raise OSError("refused")

        monkeypatch.setattr(httpsvc, "_restrict_key_permissions_windows", refuse)
        with caplog.at_level(logging.WARNING, logger="unipad.host.httpsvc"):
            httpsvc._restrict_key_permissions(material.key_path)
        assert "OSError" in caplog.text
        assert str(material.key_path) not in caplog.text


class TestPackageDeliveryIsStreamed:
    """A 4 GiB IPA is a normal package here, so nothing may be read whole."""

    def test_a_package_is_never_read_into_memory(
        self, server: PackageServer, monkeypatch: pytest.MonkeyPatch
    ) -> None:
        def refuse(*args: object, **kwargs: object) -> bytes:
            raise AssertionError("the package must be streamed, not read whole")

        monkeypatch.setattr(Path, "read_bytes", refuse)
        context = _verified_client_context(server.cert_path)
        status, body = _get(context, f"{server.url}/packages/app.ipa")
        assert status == 200
        assert body == b"IPA-PAYLOAD-ONE"

    def test_the_index_hashes_in_chunks_too(
        self, server: PackageServer, pkg_root: Path, monkeypatch: pytest.MonkeyPatch
    ) -> None:
        # The index is the first request of every install, and it used to read
        # every package whole just to hash it.
        expected = {
            entry.name: hashlib.sha256(entry.read_bytes()).hexdigest()
            for entry in sorted(pkg_root.iterdir())
            if entry.is_file()
        }

        def refuse(*args: object, **kwargs: object) -> bytes:
            raise AssertionError("the index must stream its digests, not read whole")

        monkeypatch.setattr(Path, "read_bytes", refuse)
        context = _verified_client_context(server.cert_path)
        status, body = _get(context, f"{server.url}{INDEX_PATH}")
        assert status == 200
        payload = json.loads(body)
        assert {entry["name"]: entry["sha256"] for entry in payload["packages"]} == expected

    def test_a_multi_chunk_package_arrives_intact(self, tmp_path: Path, cert_dir: Path) -> None:
        # A payload that is not a whole number of chunks, so the final short
        # read has to be written too.
        pattern = bytes(range(256))
        payload = pattern * (3 * 1024 * 1024 // len(pattern)) + pattern[:4352]
        root = tmp_path / "big"
        root.mkdir()
        (root / "big.ipa").write_bytes(payload)

        with PackageServer(root=root, cert_directory=cert_dir, port=0) as running:
            context = _verified_client_context(running.cert_path)
            with urllib.request.urlopen(
                f"{running.url}/packages/big.ipa", context=context, timeout=60
            ) as response:
                assert response.status == 200
                assert int(response.headers["Content-Length"]) == len(payload)
                assert response.read() == payload

    def test_the_stream_stops_at_the_promised_length(
        self, tmp_path: Path, monkeypatch: pytest.MonkeyPatch
    ) -> None:
        # The published Content-Length is the contract: a package that grew
        # between stat() and the read must not put more bytes on the wire than
        # the client was told to expect, or the next response on this socket is
        # corrupt for any client that reads exactly that many bytes.
        root = tmp_path / "packages"
        root.mkdir()
        (root / "app.ipa").write_bytes(b"IPA-PAYLOAD-ONE")

        handler = PackageRequestHandler.__new__(PackageRequestHandler)
        handler.command = "GET"
        handler.close_connection = False
        handler.wfile = io.BytesIO()
        handler.send_response = lambda status: None  # type: ignore[method-assign]
        handler.send_header = lambda name, value: None  # type: ignore[method-assign]
        handler.end_headers = lambda: None  # type: ignore[method-assign]
        handler.server = SimpleNamespace(package_root=root)  # type: ignore[attr-defined]

        real_open = Path.open

        def growing_open(self: Path, mode: str, *args: object, **kwargs: object) -> io.IOBase:
            handle = real_open(self, mode, *args, **kwargs)
            if self.name == "app.ipa":
                return io.BytesIO(b"IPA-PAYLOAD-ONE" + b"BYTES-NO-ONE-PROMISED")
            return handle

        monkeypatch.setattr(Path, "open", growing_open)
        handler._send_package("app.ipa")
        assert handler.wfile.getvalue() == b"IPA-PAYLOAD-ONE"


class TestIndexIsNotRehashedPerRequest:
    """``GET /index.json`` is the guest's first request of every install.

    It used to re-read and re-hash the whole package directory on *every*
    request: measured on this host, 19.2 s to answer a 260-byte question over
    3.5 GiB of packages, and the same ~2.2 GiB memory ceiling as the unstreamed
    package body.  ADR-0008 gives the service a production caller, so that cost
    is now on the install path rather than inside a test.
    """

    def test_a_second_index_request_does_not_rehash_the_packages(
        self, server: PackageServer, monkeypatch: pytest.MonkeyPatch
    ) -> None:
        calls: list[str] = []
        real_digest = httpsvc._file_digest

        def counting(path: Path) -> str:
            calls.append(path.name)
            return real_digest(path)

        monkeypatch.setattr(httpsvc, "_file_digest", counting)
        context = _verified_client_context(server.cert_path)

        first_status, first_body = _get(context, f"{server.url}{INDEX_PATH}")
        second_status, second_body = _get(context, f"{server.url}{INDEX_PATH}")

        assert first_status == second_status == 200
        assert first_body == second_body
        # Four files in ``pkg_root`` (nested/inner.ipa is not in the index -- the
        # index is one level deep), hashed once across two requests rather than
        # once per request.
        assert sorted(calls) == ["app.ipa", "lib.dylib", "notes.txt"]

    def test_a_package_that_changed_is_rehashed(
        self, server: PackageServer, pkg_root: Path, monkeypatch: pytest.MonkeyPatch
    ) -> None:
        """A cache that never invalidates answers with a stale digest.

        The transfer window is short, but nothing stops a package being
        rewritten under a running service, and an index that still names the old
        digest would send the guest after bytes that no longer exist.
        """
        calls: list[str] = []
        real_digest = httpsvc._file_digest

        def counting(path: Path) -> str:
            calls.append(path.name)
            return real_digest(path)

        monkeypatch.setattr(httpsvc, "_file_digest", counting)
        context = _verified_client_context(server.cert_path)

        _get(context, f"{server.url}{INDEX_PATH}")
        before = calls.count("app.ipa")

        target = pkg_root / "app.ipa"
        target.write_bytes(b"IPA-PAYLOAD-ONE-REWRITTEN")

        _status, body = _get(context, f"{server.url}{INDEX_PATH}")
        payload = {entry["name"]: entry for entry in json.loads(body)["packages"]}

        assert payload["app.ipa"]["sha256"] == hashlib.sha256(
            b"IPA-PAYLOAD-ONE-REWRITTEN"
        ).hexdigest()
        assert payload["app.ipa"]["size"] == len(b"IPA-PAYLOAD-ONE-REWRITTEN")
        assert calls.count("app.ipa") == before + 1

    def test_a_package_that_vanished_leaves_the_index(
        self, server: PackageServer, pkg_root: Path
    ) -> None:
        context = _verified_client_context(server.cert_path)

        _status, body = _get(context, f"{server.url}{INDEX_PATH}")
        assert "lib.dylib" in {entry["name"] for entry in json.loads(body)["packages"]}

        (pkg_root / "lib.dylib").unlink()
        _status, body = _get(context, f"{server.url}{INDEX_PATH}")
        listed = {entry["name"] for entry in json.loads(body)["packages"]}
        assert "lib.dylib" not in listed
        assert "app.ipa" in listed


class TestMalformedRequestPath:
    """A percent-encoded NUL used to kill the connection instead of answering."""

    def test_a_percent_encoded_nul_is_not_a_usable_path(self) -> None:
        handler = PackageRequestHandler.__new__(PackageRequestHandler)
        handler.path = "/packages/Hello%00.ipa"  # type: ignore[attr-defined]
        assert handler._safe_path() is None

    def test_a_percent_encoded_nul_gets_a_status(self, server: PackageServer) -> None:
        import http.client

        context = _verified_client_context(server.cert_path)
        connection = http.client.HTTPSConnection(
            "127.0.0.1", server.port, context=context, timeout=15
        )
        try:
            connection.request("GET", "/packages/Hello%00.ipa")
            first = connection.getresponse()
            assert first.status == 400
            first.read()
            # The documented contract is to keep the connection usable for the
            # next request, so the very next request on the same socket works.
            connection.request("GET", INDEX_PATH)
            second = connection.getresponse()
            assert second.status == 200
            assert json.loads(second.read())["packages"]
        finally:
            connection.close()


