class TestPortValidation:
    """One validator, one message, and it runs at bind time too."""

    @pytest.mark.parametrize("bad", [-1, 65536, True, "8443", 8443.0, None])
    def test_the_server_and_the_validator_agree(self, pkg_root: Path, bad: object) -> None:
        with pytest.raises(UniPadError) as from_constructor:
            PackageServer(root=pkg_root, port=bad)  # type: ignore[arg-type]
        assert from_constructor.value.code == ErrorCode.CONFIG_INVALID
        assert from_constructor.value.details == {"port": repr(bad)}

        with pytest.raises(UniPadError) as from_validator:
            httpsvc._validate_port(bad, "port")  # type: ignore[arg-type]
        assert from_validator.value.to_dict() == from_constructor.value.to_dict()

    def test_the_port_is_validated_again_at_bind_time(self, pkg_root: Path) -> None:
        # ``port`` and ``host`` are public attributes, so a caller can move them
        # after construction.  The bind is the operation that must never see a
        # nonsense port -- and must report it as a config fault, not as a raw
        # OverflowError out of the socket layer.
        running = PackageServer(root=pkg_root, port=0)
        running.port = 99999
        try:
            with pytest.raises(UniPadError) as excinfo:
                running.start()
            assert excinfo.value.code == ErrorCode.CONFIG_INVALID
            assert excinfo.value.details == {"port": "99999"}
        finally:
            running.stop()

    def test_the_loopback_pinning_is_rechecked_at_bind_time(self, pkg_root: Path) -> None:
        running = PackageServer(root=pkg_root, port=0)
        running.host = "0.0.0.0"
        try:
            with pytest.raises(UniPadError) as excinfo:
                running.start()
            assert excinfo.value.code == ErrorCode.CONFIG_INVALID
        finally:
            running.stop()


