class TestTransferWindowEvidence:
    """What PRD 3.2 P1 (1) acceptance reads: where the bytes came from, and
    what is *not* proven about the guest half of the fetch."""

    def test_the_evidence_names_the_url_that_actually_listened(
        self, server: PackageServer, pkg_root: Path
    ) -> None:
        evidence = httpsvc.service_evidence(
            server, package_name="app.ipa", package_sha256="a" * 64
        )
        # The port is read back off the bound socket, not off the requested
        # argument: this server was built with port=0, and 0 is not a port.
        assert evidence["port"] == server.port
        assert evidence["port"] != 0
        assert evidence["service_url"] == f"https://127.0.0.1:{server.port}"
        assert evidence["guest_url"] == f"https://10.0.2.2:{server.port}/index.json"
        assert evidence["bind_host"] == DEFAULT_LOOPBACK_HOST
        assert evidence["transport"] == "https"
        assert evidence["package_name"] == "app.ipa"
        assert evidence["package_sha256"] == "a" * 64

    def test_the_evidence_carries_the_fingerprint_a_guest_would_pin(
        self, server: PackageServer
    ) -> None:
        evidence = httpsvc.service_evidence(
            server, package_name="app.ipa", package_sha256="a" * 64
        )
        assert evidence["certificate_fingerprint"] == server.fingerprint
        assert len(evidence["certificate_fingerprint"]) == 64

    def test_the_evidence_never_claims_the_guest_fetch_was_verified(
        self, server: PackageServer
    ) -> None:
        # This host has no guest, so nothing here observed a guest fetch.  A
        # ``True`` would be a verification nobody performed (PRD 9.2), and it
        # would let a gate pass on a transport that was never exercised.
        evidence = httpsvc.service_evidence(
            server, package_name="app.ipa", package_sha256="a" * 64
        )
        assert evidence["guest_fetch_verified"] is False
        assert evidence["guest_fetch_status"] == "unverified_no_guest_implementation"

    def test_the_evidence_reports_the_scheme_actually_served(self, pkg_root: Path) -> None:
        # The ADR-0008 caller never relaxes TLS, but the evidence is a
        # measurement: a plaintext server must not be described as https.
        with PackageServer(
            root=pkg_root, port=0, tls=False, allow_plaintext=True
        ) as plaintext:
            assert httpsvc.service_evidence(
                plaintext, package_name="app.ipa", package_sha256="a" * 64
            )["transport"] == "http"

    def test_the_boundaries_did_not_move_for_the_caller(self, pkg_root: Path) -> None:
        # Loopback and TLS are the ADR-0008 defaults and there is no argument
        # the caller passes to reach anything else: the only way to build a
        # plaintext or non-loopback server is to opt in explicitly, by name.
        with PackageServer(root=pkg_root, port=0) as server:
            assert server.host == DEFAULT_LOOPBACK_HOST
            assert server.tls is True
            assert server._allow_plaintext is False
            assert server._allow_non_loopback is False

        with pytest.raises(UniPadError) as plaintext:
            PackageServer(root=pkg_root, port=0, tls=False)
        assert plaintext.value.code == ErrorCode.CONFIG_INVALID

        with pytest.raises(UniPadError) as non_loopback:
            PackageServer(root=pkg_root, port=0, host="0.0.0.0")
        assert non_loopback.value.code == ErrorCode.CONFIG_INVALID

    def test_a_bound_port_is_refused_rather_than_moved(self, pkg_root: Path, cert_dir: Path) -> None:
        # ADR-0008 decision 4: a port already in use is a refusal, never a
        # silent retry elsewhere, because the recorded URL must describe what
        # actually listened.  A retry would publish a port the caller never
        # asked for while the evidence still named the first one.
        import socket

        with socket.socket() as occupied:
            occupied.bind((DEFAULT_LOOPBACK_HOST, 0))
            occupied.listen(1)
            port = occupied.getsockname()[1]
            refused = PackageServer(root=pkg_root, cert_directory=cert_dir, port=port)
            try:
                with pytest.raises(UniPadError) as excinfo:
                    refused.start()
                assert excinfo.value.code == ErrorCode.TRANSFER_FAILED
                # The refusal names the port that was refused, so the operator
                # can see which listener is in the way.
                assert excinfo.value.details["port"] == port
                # ... and nothing is left half-listening on a port of the
                # kernel's choosing.
                assert refused.is_running is False
            finally:
                refused.stop()

    def test_the_evidence_is_plain_json_with_no_host_paths(
        self, server: PackageServer, pkg_root: Path
    ) -> None:
        # PRD 9.2: the evidence goes into a run directory an operator reads, so
        # it must serialize and must not carry the machine's own layout -- on
        # this host an absolute path embeds the Windows username.
        evidence = httpsvc.service_evidence(
            server, package_name="app.ipa", package_sha256="a" * 64
        )
        assert json.loads(json.dumps(evidence)) == evidence
        assert str(pkg_root) not in json.dumps(evidence)
        assert server.material.cert_directory is None or str(
            server.material.cert_directory
        ) not in json.dumps(evidence)

    def test_the_evidence_carries_no_windows_paths_or_host_layout(
        self, server: PackageServer, pkg_root: Path
    ) -> None:
        # PRD 9.2: the evidence goes into a run directory an operator reads, so
        # it must serialize and must not carry the machine's own layout.
        evidence = httpsvc.service_evidence(
            server, package_name="app.ipa", package_sha256="a" * 64
        )
        assert json.loads(json.dumps(evidence)) == evidence
        for value in evidence.values():
            if isinstance(value, str):
                assert "\\" not in value
                assert str(pkg_root) not in value


class TestNoTestIsSilentlyDiscarded:
    """A test defined twice in one scope is a test that never runs.

    Python keeps the *last* definition and drops the earlier one without a
    word, so a duplicated name costs real coverage and looks like a test that
    passes.  This happened here once already: two members of
    ``TestTransferWindowEvidence`` shared the name
    ``test_the_evidence_is_plain_json_with_no_host_paths``, and the first
    body's assertion -- that the certificate *directory* never reaches the
    evidence -- was silently thrown away.
    """

    def test_no_two_functions_in_one_scope_share_a_name(self) -> None:
        import ast
        import inspect
        import sys
        import textwrap

        source = textwrap.dedent(inspect.getsource(sys.modules[__name__]))
        tree = ast.parse(source)

        def duplicates(names: list[str]) -> list[str]:
            return sorted({name for name in names if names.count(name) > 1})

        module_names = [
            node.name
            for node in tree.body
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
        ]
        assert duplicates(module_names) == []
        for node in tree.body:
            if not isinstance(node, ast.ClassDef):
                continue
            class_names = [
                child.name
                for child in node.body
                if isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef))
            ]
            assert duplicates(class_names) == [], (
                f"{node.name} defines the same name twice"
            )
